function transform() {
    // System property name containing the JSON array of scripts
    var systemProperty = 'sam.implementation.user.groups';

    // Object to hold the result
    var result = {
        user_groups: [] // Array to store user group objects
    };

    // Function to fetch the JSON content from the system property
    function fetchSystemProperty(propertyName) {
        try {
            var propertyValue = gs.getProperty(propertyName); // Get the JSON string from the system property
            if (propertyValue) {
                return JSON.parse(propertyValue); // Parse the JSON content
            }
        } catch (e) {
            gs.log("Error parsing system property " + propertyName + ": " + e.message, "Transform Script");
        }
        return []; // Return an empty array if there's an error or no value
    }

    // Fetch the JSON array from the system property
    var scriptList = fetchSystemProperty(systemProperty);

    // Process each item in the array
    scriptList.forEach(function(item) {
        // Validate and add to the result array
        if (item.Group) {
            result.user_groups.push({
                group: item.Group.trim(), // Group name
                description: item.Description ? item.Description.trim() : '', // Description field, if available
                contains_roles: item.Contains_roles || false, // Contains roles field, default to false
                key: item.key || '', // Unique key for the group, if available
                url: item.url || '' // URL field, if available
            });
        }
    });

    // Return the structured result
    return result;
}
